// ============================================================
// KARAN PANEL - ALL IN ONE SERVER (website + admin + bot runner)
// GitHub par sirf ye 1 file (server.js) daalo, phir Render par deploy karo.
// Render: Build Command  ->  npm install firebase-admin
//         Start Command  ->  node server.js
// Environment Variables:
//   ADMIN_EMAILS  = aapka-admin@gmail.com   (comma se kai email)
//   FIREBASE_KEY  = service account JSON (poora text)   [bot hosting ke liye]
// Website: https://YOUR-APP.onrender.com    Admin: https://YOUR-APP.onrender.com/admin
// ============================================================
const http = require('http'), fs = require('fs'), path = require('path'), { spawn, execSync } = require('child_process');
const PORT = process.env.PORT || 3000;
const B = (s) => Buffer.from(s, 'base64').toString('utf8');
const INDEX_HTML = B("");
const ADMIN_TPL = B("");
const emails = (process.env.ADMIN_EMAILS || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
if (!emails.length) console.warn('[WARN] ADMIN_EMAILS set nahi hai - koi bhi logged-in Firebase user admin kholega. Set kar do!');
const ADMIN_HTML = ADMIN_TPL.replace('__ADMIN_EMAILS__', JSON.stringify(emails));
const send = (res, code, type, body) => { res.writeHead(code, { 'Content-Type': type, 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer-when-downgrade' }); res.end(body); };
http.createServer((req, res) => {
  const p = req.url.split('?')[0].replace(/\/+$/, '') || '/';
  if (p === '/' || p === '/index.html') return send(res, 200, 'text/html; charset=utf-8', INDEX_HTML);
  if (p === '/admin' || p === '/admin.html') return send(res, 200, 'text/html; charset=utf-8', ADMIN_HTML);
  if (p === '/healthz') return send(res, 200, 'text/plain', 'ok');
  send(res, 404, 'text/plain', 'Not found');
}).listen(PORT, () => console.log('Server chalu: port ' + PORT));

// ---------------- BOT RUNNER ----------------
(function () {
  if (!process.env.FIREBASE_KEY) return console.warn('[Runner] FIREBASE_KEY nahi mila - bot hosting band, website chalu hai.');
  let admin; try { admin = require('firebase-admin'); } catch (e) { return console.error('[Runner] Build Command me "npm install firebase-admin" daalo'); }
  try { admin.initializeApp({ credential: admin.credential.cert(JSON.parse(process.env.FIREBASE_KEY)), databaseURL: process.env.FIREBASE_DB_URL || 'https://karan-panel-default-rtdb.firebaseio.com' }); } catch (e) { return console.error('[Runner] FIREBASE_KEY galat JSON hai:', e.message); }
  const db = admin.database(), procs = {}, DIR = path.join(__dirname, 'bots');
  const log = (id, m, l = '') => { db.ref('bot_logs/' + id).push({ t: Date.now(), l, m: String(m).slice(0, 2000) }); db.ref('bot_logs/' + id).once('value', s => { const n = s.numChildren(); if (n > 400) { let i = 0; s.forEach(c => { if (i++ < n - 300) c.ref.remove(); }); } }); };
  const status = (id, st) => db.ref('bots/' + id).update({ status: st });
  function stop(id) { if (procs[id]) { procs[id].kill('SIGKILL'); delete procs[id]; } }
  function start(id, b) {
    stop(id); const dir = path.join(DIR, id); fs.mkdirSync(dir, { recursive: true });
    const f = path.join(dir, b.fileName); fs.writeFileSync(f, Buffer.from(b.data, 'base64'));
    try { if (/\.zip$/i.test(b.fileName)) execSync(`unzip -o "${f}" -d "${dir}"`); if (fs.existsSync(path.join(dir, 'package.json'))) { log(id, 'npm install...', 'sys'); execSync('npm install --omit=dev', { cwd: dir }); } if (fs.existsSync(path.join(dir, 'requirements.txt'))) execSync('pip install -r requirements.txt', { cwd: dir }); } catch (e) { log(id, 'Setup error: ' + e.message, 'err'); return status(id, 'error'); }
    const p = spawn(b.runtime === 'python' ? 'python3' : 'node', [b.entry], { cwd: dir, env: { PATH: process.env.PATH, HOME: process.env.HOME || '/tmp', NODE_ENV: 'production' } }); procs[id] = p; status(id, 'running'); log(id, 'Bot started', 'sys');
    p.stdout.on('data', d => log(id, d)); p.stderr.on('data', d => log(id, d, 'err'));
    p.on('close', c => { delete procs[id]; log(id, 'Exited code ' + c, c ? 'err' : 'sys'); status(id, c ? 'error' : 'stopped'); });
    const t = setTimeout(() => procs[id] === p && (log(id, 'Max runtime limit', 'sys'), stop(id)), 24 * 36e5); p.on('close', () => clearTimeout(t));
  }
  db.ref('bots').on('child_added', s => handle(s)); db.ref('bots').on('child_changed', s => handle(s));
  async function handle(s) {
    const id = s.key, b = s.val(); if (!b.cmd) return; await db.ref('bots/' + id + '/cmd').set('');
    if (b.cmd === 'stop') { stop(id); status(id, 'stopped'); log(id, 'Stopped', 'sys'); }
    else if (b.cmd === 'delete') { stop(id); fs.rmSync(path.join(DIR, id), { recursive: true, force: true }); }
    else { const lim = (await db.ref('bot_settings/freeBots').once('value')).val() ?? 1; const pr = (await db.ref('bot_premium/' + b.uid).once('value')).val(); if (b.createdAt && pr && pr.expiresAt < Date.now() && Object.keys((await db.ref('bots').orderByChild('uid').equalTo(b.uid).once('value')).val() || {}).length > lim) { log(id, 'Premium expire - bot band', 'err'); return status(id, 'stopped'); } start(id, b); }
  }
  setInterval(async () => { for (const id of Object.keys(procs)) { const b = (await db.ref('bots/' + id).once('value')).val(); if (!b) stop(id); } }, 6e4);
  console.log('[Runner] Bot runner chalu');
})();
process.on('uncaughtException', e => console.error('Error:', e.message));
process.on('unhandledRejection', e => console.error('Rejection:', e && e.message));
